#include <signal.h>
#include <sys/types.h>
#include <linux/errno.h>

int rt_sigqueueinfo(pid_t pid, int sig, siginfo_t __user *uinfo) {
    siginfo_t info;
    int ret;

    if (copy_from_user(&info, uinfo, sizeof(siginfo_t)))
        return -EFAULT;

    if (info.si_code < 0 || info.si_code >= _NSIGCODE)
        return -EINVAL;

    if (info.si_code >= 0 && info.si_code < __SI_KILL) {
        if (info.si_code != 0)
            return -EPERM;
    }

    info.si_signo = sig;
    ret = kill_proc_info(sig, &info, pid);

    return ret;
}

#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/signal.h>

int rt_sigqueueinfo(pid_t pid, int sig, siginfo_t __user *uinfo) {
    siginfo_t info;
    int ret;

    if (copy_from_user(&info, uinfo, sizeof(siginfo_t)))
        return -EFAULT;

    if (info.si_code < 0 || info.si_code >= _NSIGCODE)
        return -EINVAL;

    if (info.si_code != SI_USER && info.si_code != SI_KERNEL &&
        info.si_code != SI_QUEUE && info.si_code != SI_TIMER &&
        info.si_code != SI_ASYNC_NP && info.si_code != SI_MESGQ)
        return -EINVAL;

    if (pid == 1 || (pid > 1 && (current->euid >> 20) != (info.si_uid >> 20)))
        return -EPERM;

    info.si_signo = sig;
    ret = kill_proc_info(sig, &info, pid);
    return ret;
}

#include <signal.h>
#include <unistd.h>
#include <sys/types.h>

int rt_sigqueueinfo(pid_t pid, int sig, siginfo_t __user *uinfo) {
    siginfo_t info;
    int ret;

    if (copy_from_user(&info, uinfo, sizeof(siginfo_t)))
        return -EFAULT;

    if (info.si_code < 0 || info.si_code >= _NSIGCODE)
        return -EINVAL;

    if (current->euid && !capable(CAP_KILL))
        return -EPERM;

    info.si_signo = sig;
    ret = kill_proc_info(sig, &info, pid);

    return ret ? ret : 0;
}
